package com.voicetxt.reader;
import android.app.*;import android.content.Intent;import android.os.Bundle;import android.view.View;import java.util.concurrent.atomic.*;
public class ChapterPickerTest extends Instrumentation {
 void check(boolean ok,String message){if(!ok)throw new AssertionError(message);}
 void ui(Runnable action){AtomicReference<Throwable> error=new AtomicReference<>();runOnMainSync(()->{try{action.run();}catch(Throwable e){error.set(e);}});if(error.get()!=null)throw new AssertionError(error.get());}
 @Override public void onCreate(Bundle b){super.onCreate(b);start();}
 @Override public void onStart(){Bundle result=new Bundle();MainActivity activity=null;boolean passed=false;try{
 activity=(MainActivity)startActivitySync(new Intent(getTargetContext(),MainActivity.class).putExtra("book_id","chapter_picker_qa").putExtra("book_name","目录功能验证").addFlags(Intent.FLAG_ACTIVITY_NEW_TASK));final MainActivity a=activity;
 long end=android.os.SystemClock.elapsedRealtime()+30000;AtomicBoolean ready=new AtomicBoolean();while(android.os.SystemClock.elapsedRealtime()<end){ui(()->ready.set(a.system.initialized&&a.offlineReady));if(ready.get())break;Thread.sleep(100);}check(ready.get(),"engines not ready");
 ui(()->{StringBuilder text=new StringBuilder();a.chapters.clear();for(int i=0;i<1100;i++){int start=text.length();String name="第"+(i+1)+"章 "+(i==999?"目标章节":"山河故事");text.append(name).append("\n这是一段用于验证目录跳转的朗读文字。\n");a.chapters.add(new MainActivity.Chapter(name,start,text.length()));}a.text=text.toString();a.position=a.chapters.get(879).start;a.showPosition(true);a.directory();});Thread.sleep(400);
 ui(()->{ChapterPicker picker=a.chapterPicker;check(picker.visible.size()==1100,"long list incomplete");check(picker.list.getFirstVisiblePosition()==879,"did not locate current chapter");View row=picker.adapter.getView(879,null,picker.list);check(row.isSelected(),"current chapter not highlighted");check(!picker.adapter.getView(878,null,picker.list).isSelected(),"non-current chapter highlighted");picker.search.setText("目标章节");check(picker.visible.size()==1&&picker.visible.get(0)==999,"search mapping incorrect");picker.list.performItemClick(picker.adapter.getView(0,null,picker.list),0,999);check(a.chapter==999&&a.position==a.chapters.get(999).start,"filtered click jumped to wrong chapter");check(a.playing,"chapter click did not start reading");a.stop();a.directory();});Thread.sleep(400);
 ui(()->{check(a.chapterPicker.search.length()==0,"search unexpectedly persisted");check(a.chapterPicker.list.getFirstVisiblePosition()==999,"reopen not at current chapter");a.chapterPicker.search.setText("不存在的章节");check(a.chapterPicker.visible.isEmpty(),"no results not empty");a.chapterPicker.search.setText("1000");check(a.chapterPicker.visible.contains(999),"numeric chapter search failed");a.chapterPicker.search.setText("");});Thread.sleep(300);
 ui(()->check(a.chapterPicker.list.getFirstVisiblePosition()==999,"clear search lost current position"));
 android.graphics.Bitmap image=getUiAutomation().takeScreenshot();try(java.io.FileOutputStream out=new java.io.FileOutputStream(new java.io.File(getTargetContext().getExternalFilesDir(null),"chapter-picker-qa.png"))){image.compress(android.graphics.Bitmap.CompressFormat.PNG,100,out);}image.recycle();
 result.putString("result","PASS: 1100 chapters; current highlight; title/number search; filtered index mapping; tap starts reading; reopen and clear search locate current; empty result");passed=true;
 }catch(Throwable e){result.putString("error",android.util.Log.getStackTraceString(e));}finally{if(activity!=null){final MainActivity a=activity;ui(()->{if(a.chapterPicker!=null)a.chapterPicker.dismiss();a.stop();a.finish();});getTargetContext().getSharedPreferences("reader_chapter_picker_qa",0).edit().clear().commit();}}finish(passed?-1:0,result);}
}
